fiera("wtm-london", "WTM – World Travel Market", "london", "Turismo", "Annuale, a novembre", "https://www.wtm.com",
 "novembre 2027 (date da confermare)", "2027-11-01", None, False, "stand-fiera-estero-padiglione",
 "Tour operator, agenzie, compagnie aeree, catene alberghiere, enti del turismo",
 "Stand per WTM Londra: stand e padiglioni per regioni, destinazioni e hotel, postazioni per appuntamenti B2B e montaggio a ExCeL London, con lo stand prodotto in Italia.",
 ["WTM – World Travel Market è la grande fiera internazionale del turismo di Londra: destinazioni, enti, tour operator, hotel e tecnologie per il travel si incontrano a novembre a ExCeL London.",
  "Come a ITB e BIT, si lavora su appuntamenti: lo stand deve avere molte postazioni, un'immagine forte della destinazione e un'accoglienza calda. Le regioni italiane espongono spesso in collettive, con trasporto e montaggio da coordinare dall'Italia e regole doganali post-Brexit da considerare."],
 [('Postazioni per appuntamenti.', 'Molti tavoli per incontri brevi con tour operator e agenzie, numerati per ritrovarsi subito.'),
  ('Immagine della destinazione.', 'Grafiche e ledwall che raccontano paesaggi, città e prodotti del territorio.'),
  ('Collettive.', "Postazioni per i co-espositori, con nome e logo di ciascuno sotto un'immagine comune."),
  ('Accoglienza.', 'Bar e degustazioni di prodotti tipici, che attirano visitatori e creano occasioni di incontro.'),
  ('Trasporto nel Regno Unito.', 'Documenti e tempi doganali pianificati, perché dopo la Brexit lo stand viaggia con pratiche dedicate.')],
 ('WTM è a novembre: per collettive si parte in primavera; il trasporto nel Regno Unito richiede qualche settimana in più per documenti e dogana, quindi la produzione si chiude a settembre. Le date ufficiali del 2027 le '
  'aggiorniamo appena escono.'),
 [('Gestite il trasporto dello stand nel Regno Unito?', 'Sì, con trasportatori partner e la documentazione doganale necessaria, pianificata con anticipo.'),
  ('Allestite anche per ITB e BIT?', 'Sì: <a href="/stand-itb-berlin/">ITB Berlin</a> e <a href="/stand-bit-milano/">BIT Milano</a>, le altre grandi fiere del turismo.'),
  ('Fate collettive regionali?', "Sì, con un unico referente per l'ente, che raccoglie materiali e testi dei co-espositori.")],
 ["Stand per WTM","Padiglioni per destinazioni","Postazioni per appuntamenti","Montaggio a ExCeL London"],
 [("/stand-itb-berlin/","Stand ITB Berlin"),("/stand-ttg-travel-experience/","Stand TTG Travel Experience"),("/calendario-fiere-turismo/","Calendario fiere del turismo")]),

